import {money,today,numeric,totals,validate,nextNumber,seed} from './model.js';
const paths={invoice:'M6 3h9l4 4v14l-3-2-3 2-3-2-4 2V3Z M14 3v5h5 M9 12h7 M9 15h5',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3',plus:'M12 5v14 M5 12h14',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',download:'M12 3v12 M7 10l5 5 5-5 M5 16v5h14v-5',arrow:'M5 12h14 M14 7l5 5-5 5',back:'M19 12H5 M10 7l-5 5 5 5',chevron:'m9 6 6 6-6 6',check:'m5 12 4 4L19 6',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',more:'M5 12h.01 M12 12h.01 M19 12h.01',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',copy:'M9 9h12v12H9z M15 5V2H2v13h3',close:'M6 6l12 12 M6 18 12 6',edit:'m15 4 5 5 M4 20l5-1L21 7l-5-5L4 14v6Z',help:'M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3 M12 18h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',shield:'M12 3 3 6v6c0 5 9 10 9 10s9-5 9-10V6l-9-3Z m-4 9 3 3 5-6',mail:'M3 5h18v14H3z m0 1 9 7 9-7',leaf:'M20 3c-12-1-18 5-15 12 5 8 17 1 15-12Z M4 21 16 9',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7',calendar:'M3 5h18v16H3z M7 2v6 M17 2v6 M3 11h18',home:'m3 10 9-7 9 7v11H3V10 M9 21v-8h6v8',logout:'M9 3H3v18h6 M10 12h12 m-5-5 5 5-5 5'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.invoice}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='claro-facturas-v1';let db;let storageOK=true;try{const raw=localStorage.getItem(KEY);db=raw?JSON.parse(raw):seed();if(!db?.invoices||!db?.clients||!db?.company)throw Error();}catch{db=seed();storageOK=false;}
let page='invoices',tab='all',query='',month='all',sort='new',active=null,errors=[],clientQuery='',saveTimer;
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const fmtDate=d=>new Intl.DateTimeFormat('es-ES',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z')).replaceAll('.','');
const client=i=>i.clientSnapshot||db.clients.find(c=>c.id===i.clientId)||{name:'Sin cliente',nif:'',address:''};
const company=i=>i.companySnapshot||db.company;
const initial=n=>n.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const colors=[['#eeece5','#98886c'],['#e7eeda','#85935e'],['#e8edf5','#7b8ca5'],['#f3e8e4','#b3887b'],['#e5efea','#6c9582']];
const avatar=c=>{const p=colors[c.color%5]||colors[0];return `<span class="client-avatar" style="--avbg:${p[0]};--avfg:${p[1]}">${esc(initial(c.name))}</span>`};
const badge=i=>`<span class="badge ${i.status==='draft'?'draft':i.originalId?'rect':''}">${i.status==='draft'?'Borrador':i.originalId?'Rectificativa':'Emitida'}</span>`;
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),3500);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(db));storageOK=true;return true;}catch{storageOK=false;toast('No se han guardado los cambios. Comprueba el almacenamiento del navegador.');return false;}}
function saveDraft(){if(active?.status==='draft'){active.updatedAt=new Date().toISOString();const ok=persist();const el=document.querySelector('.save-status');if(el)el.innerHTML=icon(ok?'check':'help')+(ok?'Guardado en este navegador':'Cambios sin guardar');}}
function navigate(next){clearTimeout(saveTimer);saveDraft();page=next;errors=[];render();window.scrollTo(0,0);}
function shell(body,title){const section=page==='clients'?'clients':page==='settings'?'settings':'invoices';app.innerHTML=`<aside class="sidebar"><div class="logo"><span class="mark">${icon('leaf')}</span>claro<span style="color:#8fa786">.</span></div><div class="workspace"><div class="avatar">${esc(initial(db.company.name))}</div><div><strong>${esc(db.company.name)}</strong><small>Mi espacio de trabajo</small></div></div><div class="navlabel">TU NEGOCIO</div><nav class="nav" aria-label="Navegación principal">${[['invoices','invoice','Facturas'],['clients','users','Clientes'],['settings','settings','Configuración']].map(([id,ic,n])=>`<button data-nav="${id}" class="${section===id?'active':''}" ${section===id?'aria-current="page"':''}>${icon(ic)}<span>${n}</span>${id==='invoices'?`<span class="count">${db.invoices.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="local-note"><strong>${icon('shield')} Tu espacio, en orden.</strong>Los cambios se guardan<br>en este navegador.</div><div class="profile"><div class="avatar">EC</div><div><strong>Mi empresa</strong><small>Espacio de demostración</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Mi espacio ${icon('chevron')} <strong>${title}</strong></div><div class="logo mobile-logo"><span class="mark">${icon('leaf')}</span>claro.</div><div class="topright"><span>Hecho para trabajar con calma</span><span class="demo"><i class="dot"></i>Modo demostración</span><button class="iconbtn" data-action="help" aria-label="Ayuda">${icon('help')}</button></div></header><div class="content">${!storageOK?'<div class="error" role="alert">El almacenamiento no está disponible. Exporta una copia antes de cerrar esta página.</div>':''}${body}<footer class="footer"><span>${icon('shield')} Un poco más de claridad en tu día a día.</span><span>Claro · Facturación sencilla</span></footer></div></main>`;}
function heading(title,sub,actions=''){return `<div class="heading"><div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`;}
function filtered(){return db.invoices.filter(i=>(tab==='all'||i.status===tab)&&(month==='all'||i.date.startsWith(month))&&(`${i.number||'borrador'} ${client(i).name} ${client(i).nif}`.toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>sort==='amount'?totals(b).total-totals(a).total:b.date.localeCompare(a.date)||b.id.localeCompare(a.id));}
function invoiceRows(){const rows=filtered();return rows.length?`<table><thead><tr><th>Factura</th><th>Cliente</th><th>Fecha ${icon('chevron').replace('<svg','<svg style="width:10px;height:10px;transform:rotate(90deg)"')}</th><th class="num">Importe</th><th>Estado</th><th aria-label="Acciones"></th></tr></thead><tbody>${rows.map(i=>`<tr><td><button class="rowlink" data-open="${i.id}">${esc(i.number||'Sin numerar')} ${i.status==='draft'?'<span class="subtle">↗</span>':''}</button></td><td><div class="clientcell">${avatar(client(i))}<div><strong>${esc(client(i).name)}</strong><small>${esc(client(i).nif||'Completar datos fiscales')}</small></div></div></td><td class="muted">${fmtDate(i.date)}</td><td class="num"><strong style="font-weight:550">${money(totals(i).total)}</strong></td><td>${badge(i)}</td><td><button class="iconbtn" data-menu="${i.id}" aria-label="Acciones de ${esc(i.number||'borrador de '+client(i).name)}">${icon('more')}</button></td></tr>`).join('')}</tbody></table>`:`<div class="empty">${icon('search')}<h3>No hay facturas que coincidan</h3><p>Prueba con otro cliente o cambia los filtros.</p><button class="btn" data-action="clear-filters">Limpiar filtros</button></div>`;}
function invoices(){const issued=db.invoices.filter(i=>i.status==='issued'),drafts=db.invoices.filter(i=>i.status==='draft');const total=issued.filter(i=>i.date.startsWith(today().slice(0,7))).reduce((n,i)=>n+totals(i).total,0);const months=[...new Set(db.invoices.map(i=>i.date.slice(0,7)))].sort().reverse();shell(heading('Tus facturas','Todo en su sitio. De la primera línea al último detalle.',`<button class="btn" data-action="export">${icon('download')} Exportar</button><button class="btn primary" data-action="new">${icon('plus')} Nueva factura</button>`)+`<section class="stats" aria-label="Resumen de facturas"><div class="stat"><div class="stat-label">${icon('invoice')} Emitido este mes</div><div class="stat-value">${money(total)}</div><small>Importe total con impuestos · datos de ejemplo</small><div class="stat-accent">${[12,18,14,24,21,31,36].map(h=>`<i style="height:${h}px"></i>`).join('')}</div></div><div class="stat"><div class="stat-label">${icon('check')} Facturas emitidas</div><div class="stat-value">${issued.length.toString().padStart(2,'0')}</div><small>Documentos listos para consultar</small></div><div class="stat"><div class="stat-label">${icon('edit')} Borradores</div><div class="stat-value">${drafts.length.toString().padStart(2,'0')}</div><small>Puedes retomarlos cuando quieras</small></div></section><section class="panel"><div class="tabsbar"><div class="tabs" role="group" aria-label="Estado de factura">${[['all','Todas',db.invoices.length],['issued','Emitidas',issued.length],['draft','Borradores',drafts.length]].map(([t,n,count])=>`<button class="tab ${t===tab?'active':''}" data-tab="${t}" aria-pressed="${t===tab}">${n}<em>${count}</em></button>`).join('')}</div><small class="muted">Tu archivo, siempre a mano</small></div><div class="toolbar"><div class="search">${icon('search')}<input id="search" aria-label="Buscar facturas" placeholder="Buscar por número o cliente…" value="${esc(query)}"></div><div class="actions"><select id="month" aria-label="Filtrar por mes"><option value="all">Todas las fechas</option>${months.map(m=>`<option value="${m}" ${month===m?'selected':''}>${new Intl.DateTimeFormat('es-ES',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(m+'-15T12:00:00Z'))}</option>`).join('')}</select><select id="sort" aria-label="Ordenar facturas"><option value="new" ${sort==='new'?'selected':''}>Más recientes</option><option value="amount" ${sort==='amount'?'selected':''}>Mayor importe</option></select></div></div><div class="tablewrap" id="rows">${invoiceRows()}</div><div class="tablefoot"><span id="result-count">${filtered().length} de ${db.invoices.length} facturas</span><span>Todos tus documentos en un único lugar</span></div></section><div class="hintcard"><div class="hint-icon">${icon('spark')}</div><div><strong>La próxima factura, un poco más fácil.</strong><p>Duplica una factura anterior y ajusta solo lo que haya cambiado.</p></div><button class="btn ghost" data-action="help">Ver consejos ${icon('arrow')}</button></div>`,'Facturas');}
function newInvoice(from=null,rect=false){clearTimeout(saveTimer);saveDraft();const id=crypto.randomUUID();active=from?{...structuredClone(from),id,date:today(),status:'draft',number:null,createdAt:new Date().toISOString(),...(rect?{originalId:from.id,reason:''}:{originalId:null})}:{id,clientId:'',date:today(),lines:[{description:'',qty:1,price:'',tax:21}],notes:db.company.notes,status:'draft',number:null,createdAt:new Date().toISOString()};delete active.clientSnapshot;delete active.companySnapshot;db.invoices.unshift(active);persist();page='editor';errors=[];render();window.scrollTo(0,0);}
function sumHTML(i){const t=totals(i);if(!Number.isFinite(t.total))return '<p class="error">Revisa los importes introducidos.</p>';return `<div class="sumrows"><div class="sumrow"><span>Base imponible</span><strong>${money(t.base)}</strong></div>${t.groups.map(g=>`<div class="sumrow"><span>IVA (${g.rate} %)</span><strong>${money(g.amount)}</strong></div>`).join('')}</div><div class="grand"><span>Total</span><strong>${money(t.total)}</strong></div>`;}
function lineHTML(l,n){return `<div class="line"><input data-line="${n}" data-key="description" aria-label="Concepto ${n+1}" placeholder="Describe tu producto o servicio" value="${esc(l.description)}"><input data-line="${n}" data-key="qty" inputmode="decimal" aria-label="Cantidad ${n+1}" value="${esc(l.qty)}"><input data-line="${n}" data-key="price" inputmode="decimal" aria-label="Precio ${n+1}" placeholder="0,00" value="${esc(l.price)}"><select data-line="${n}" data-key="tax" aria-label="IVA ${n+1}">${[21,10,4,0].map(t=>`<option value="${t}" ${Number(l.tax)===t?'selected':''}>${t} %</option>`).join('')}</select><strong data-line-total="${n}">${money((numeric(l.qty)||0)*(numeric(l.price)||0))}</strong><button class="iconbtn" data-remove-line="${n}" aria-label="Eliminar concepto ${n+1}">${icon('trash')}</button></div>`;}
function editor(){if(!active)return navigate('invoices');const c=db.clients.find(c=>c.id===active.clientId);shell(heading(active.originalId?'Nueva rectificativa':'Nueva factura','Los pequeños detalles hacen un trabajo bien hecho.',`<span class="save-status">${icon('check')} Guardado en este navegador</span><button class="btn" data-nav="invoices">Cerrar</button>`)+`${errors.length?`<div class="error" role="alert"><strong>Revisa estos datos antes de continuar:</strong><ul>${errors.map(([id,m])=>`<li>${esc(m)}</li>`).join('')}</ul></div>`:''}<div class="formgrid"><div><section class="panel formpanel"><div class="sectionhead"><h2><span class="step">1</span>Cliente y datos de factura</h2><button class="btn ghost" data-action="new-client">${icon('plus')} Nuevo cliente</button></div><div class="fields"><div class="field full"><label for="client">¿A quién facturamos?</label><select id="client"><option value="">Selecciona un cliente</option>${db.clients.map(c=>`<option value="${c.id}" ${c.id===active.clientId?'selected':''}>${esc(c.name)} · ${esc(c.nif)}</option>`).join('')}</select></div><div class="field"><label for="date">Fecha de expedición</label><input id="date" type="date" value="${active.date}"></div><div class="field"><label for="series">Serie</label><input id="series" value="${active.originalId?'R · Rectificativas':'F · Facturas ordinarias'}" readonly><small>El número se asignará al emitir.</small></div></div>${c?`<div class="client-preview"><strong>${esc(c.name)}</strong> · ${esc(c.nif)}<br>${esc(c.address)}<br>${esc(c.email)}</div>`:''}</section><section class="panel formpanel" id="lines"><div class="sectionhead"><h2><span class="step">2</span>Conceptos</h2><small class="muted">Precios sin IVA</small></div><div class="tablewrap"><div class="lines"><div class="line-head"><span>Concepto</span><span>Cant.</span><span>Precio €</span><span>IVA</span><span class="num">Importe</span><span></span></div><div id="line-list">${active.lines.map(lineHTML).join('')}</div></div></div><button class="btn ghost" data-action="add-line">${icon('plus')} Añadir concepto</button></section><section class="panel formpanel"><div class="sectionhead"><h2><span class="step">3</span>Un último detalle</h2><small class="muted">Opcional</small></div>${active.originalId?`<div class="field" style="margin-bottom:18px"><label for="reason">Motivo de rectificación</label><input id="reason" value="${esc(active.reason)}" placeholder="Explica qué corrige este documento"></div>`:''}<div class="field"><label for="notes">Notas para el cliente</label><textarea id="notes" placeholder="Una nota, las condiciones o un agradecimiento…">${esc(active.notes)}</textarea><small>Aparecerán al final del documento.</small></div></section></div><aside class="panel summary"><h2>Resumen de factura</h2><div id="summary-values">${sumHTML(active)}</div><button class="btn primary" data-action="review">Revisar factura ${icon('arrow')}</button><button class="btn ghost" data-action="save-close">Guardar y cerrar</button><p class="summary-note">${icon('shield')} Todavía es un borrador. Podrás revisar todos los datos antes de emitir.</p><p class="switchline">Modo de prueba · Los documentos generados no tienen validez fiscal.</p></aside></div>`,'Nueva factura');}
function paper(i){const c=client(i),co=company(i);return `<article class="invoice-paper" aria-label="Vista previa del documento"><div class="paper-top"><div class="logo"><span class="mark">${icon('leaf')}</span>${esc(co.name)}</div><div><h2>${i.originalId?'Rectificativa':'Factura'}</h2><div class="paper-number">${esc(i.number||'Borrador · Sin numerar')}</div></div></div><div class="paper-address"><div><label>De</label><strong>${esc(co.name)}</strong><br>${esc(co.nif)}<br>${esc(co.address)}<br>${esc(co.email)}</div><div><label>Para</label><strong>${esc(c.name)}</strong><br>${esc(c.nif)}<br>${esc(c.address)}<br>${esc(c.email||'')}</div></div><div class="paper-meta"><div><small>Fecha de expedición</small>${fmtDate(i.date)}</div><div><small>Moneda</small>EUR · Euro</div>${i.originalId?`<div><small>Factura original</small>${esc(db.invoices.find(x=>x.id===i.originalId)?.number||'')}</div>`:''}</div><table class="paper-table"><thead><tr><th>Concepto</th><th class="num">Cant.</th><th class="num">Precio</th><th class="num">IVA</th><th class="num">Importe</th></tr></thead><tbody>${i.lines.map(l=>`<tr><td>${esc(l.description)}</td><td class="num">${esc(l.qty)}</td><td class="num">${money(numeric(l.price))}</td><td class="num">${l.tax} %</td><td class="num">${money(Math.round(numeric(l.qty)*numeric(l.price)*100)/100)}</td></tr>`).join('')}</tbody></table><div class="paper-total">${sumHTML(i)}</div>${i.reason?`<div class="paper-notes"><strong>Motivo de rectificación</strong><br>${esc(i.reason)}</div>`:''}<div class="paper-notes">${esc(i.notes||'')}${co.iban?`<br>Cuenta de pago: ${esc(co.iban)}`:''}</div><div class="paper-demo">DOCUMENTO DE EJEMPLO · SIN VALIDEZ FISCAL</div></article>`;}
function review(){if(!active)return navigate('invoices');const draft=active.status==='draft';shell(heading(draft?'Todo listo para revisar':active.number,draft?'Un último vistazo antes de dar el siguiente paso.':`${client(active).name} · ${fmtDate(active.date)}`,`<button class="btn" data-action="${draft?'back-edit':'back-list'}">${icon('back')} ${draft?'Volver a editar':'Volver a facturas'}</button>`)+`<div class="reviewlayout">${paper(active)}<aside class="panel reviewaside"><h2>${draft?'Revisa con tranquilidad':'Tu factura, preparada'}</h2><p>${draft?'Comprueba el cliente, los conceptos y los importes. Al emitir se guardará una copia del documento con su número.':'Puedes imprimir este documento o guardarlo como PDF desde el diálogo de impresión.'}</p>${badge(active)}${draft?`<button class="btn primary" data-action="issue">Emitir de prueba ${icon('arrow')}</button>`:`<button class="btn primary" data-action="print">${icon('download')} Imprimir / PDF</button><button class="btn" data-action="duplicate">${icon('copy')} Duplicar factura</button>${!active.originalId?`<button class="btn ghost" data-action="rectify">${icon('edit')} Crear rectificativa</button>`:''}`}<p class="review-aside-meta">Entorno de demostración.<br>Sin conexión con la AEAT.<br>Datos guardados en este navegador.</p></aside></div>`,'Revisión de factura');}
function clients(){const list=db.clients.filter(c=>(c.name+' '+c.nif).toLowerCase().includes(clientQuery.toLowerCase()));shell(heading('Tus clientes','Los datos de siempre, una sola vez.',`<button class="btn primary" data-action="new-client">${icon('plus')} Nuevo cliente</button>`)+`<div class="search" style="margin-bottom:25px">${icon('search')}<input id="client-search" aria-label="Buscar clientes" placeholder="Buscar por nombre o NIF…" value="${esc(clientQuery)}"></div><div class="clientcards" id="client-cards">${clientCards(list)}</div>`,'Clientes');}
function clientCards(list){return list.length?list.map(c=>`<article class="panel clientcard">${avatar(c)}<h3>${esc(c.name)}</h3><p>${esc(c.nif)}<br>${esc(c.email||'Sin correo electrónico')}<br>${esc(c.address||'Sin dirección')}</p><button class="btn" data-edit-client="${c.id}">${icon('edit')} Editar datos</button></article>`).join(''):'<div class="empty"><h3>No encontramos ese cliente</h3><p>Prueba con otro nombre o NIF.</p></div>';}
function settings(){const co=db.company;shell(heading('Tu empresa','Una buena base para todas tus facturas.')+`<form id="settings-form" class="settings"><section class="panel formpanel"><div class="sectionhead"><h2>Datos de facturación</h2>${icon('home')}</div><div class="fields"><div class="field full"><label for="company-name">Razón social</label><input id="company-name" name="name" value="${esc(co.name)}" required maxlength="100"></div><div class="field"><label for="company-nif">NIF</label><input id="company-nif" name="nif" value="${esc(co.nif)}" required maxlength="20"></div><div class="field"><label for="company-email">Correo electrónico</label><input id="company-email" name="email" type="email" value="${esc(co.email)}"></div><div class="field full"><label for="company-address">Dirección fiscal completa</label><input id="company-address" name="address" value="${esc(co.address)}" required maxlength="200"></div><div class="field full"><label for="company-iban">Cuenta bancaria (opcional)</label><input id="company-iban" name="iban" value="${esc(co.iban)}" placeholder="ES00 0000 0000 0000 0000 0000"></div><div class="field full"><label for="company-notes">Nota predeterminada</label><textarea id="company-notes" name="notes">${esc(co.notes)}</textarea></div></div><button class="btn primary" type="submit">${icon('check')} Guardar cambios</button></section><section class="panel formpanel"><h2>Tu información</h2><p class="summary-note">Esta versión guarda los datos únicamente en este navegador. Puedes descargar una copia en JSON para conservarlos o restaurarlos en otro navegador.</p><div class="actions"><button class="btn" type="button" data-action="backup">${icon('download')} Descargar copia</button><button class="btn" type="button" data-action="restore">Restaurar copia</button></div><input type="file" id="backup-file" accept=".json,application/json" hidden><p class="summary-note">Numeración de prueba: F-año-número y R-año-número. La configuración fiscal y la emisión real se habilitarán cuando esté integrada la normativa aplicable a la empresa.</p></section></form>`,'Configuración');}
function render(){({invoices,editor,review,clients,settings}[page]||invoices)();}
function clientModal(id){const c=db.clients.find(c=>c.id===id)||{name:'',nif:'',email:'',address:''};modal.innerHTML=`<button class="iconbtn close" data-action="close-modal" aria-label="Cerrar">${icon('close')}</button><h2>${id?'Editar cliente':'Un nuevo cliente'}</h2><p>Guarda sus datos y tenlos a mano para la próxima factura.</p><form id="client-form" data-id="${id||''}"><div class="fields"><div class="field full"><label for="c-name">Nombre o razón social</label><input id="c-name" name="name" value="${esc(c.name)}" required maxlength="100"></div><div class="field"><label for="c-nif">NIF / Identificación fiscal</label><input id="c-nif" name="nif" value="${esc(c.nif)}" required maxlength="25"></div><div class="field"><label for="c-email">Correo electrónico</label><input id="c-email" name="email" type="email" value="${esc(c.email)}"></div><div class="field full"><label for="c-address">Dirección fiscal</label><input id="c-address" name="address" value="${esc(c.address)}" required maxlength="200"></div></div><div class="actions"><button type="button" class="btn ghost" data-action="close-modal">Cancelar</button><button type="submit" class="btn primary">${id?'Guardar cambios':'Guardar cliente'}</button></div></form>`;modal.showModal();}
function showHelp(){modal.innerHTML=`<button class="iconbtn close" data-action="close-modal" aria-label="Cerrar">${icon('close')}</button><h2>Un espacio para facturar con calma</h2><p>1. Crea una factura y selecciona un cliente.<br>2. Añade tus conceptos y revisa los importes.<br>3. Emite un documento de prueba y guárdalo como PDF.<br><br>Desde el menú de cada factura puedes duplicarla. Los borradores se guardan automáticamente. En Configuración puedes descargar una copia de tus datos.<br><br><strong>Esta es una demostración funcional:</strong> no tiene conexión fiscal, envío de correo ni sincronización entre dispositivos. Los documentos están identificados como ejemplos sin validez fiscal.</p><button class="btn primary" data-action="close-modal">Entendido</button>`;modal.showModal();}
function download(content,name,type){const blob=new Blob([content],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function csvExport(){const csvCell=v=>'"'+String(v??'').replaceAll('"','""').replace(/^[=+@\-]/,"'"+'$&')+'"';const rows=[['Número','Cliente','NIF','Fecha','Base','IVA','Total','Estado'],...filtered().map(i=>{const t=totals(i);return[i.number||'Borrador',client(i).name,client(i).nif,i.date,t.base.toFixed(2),t.vat.toFixed(2),t.total.toFixed(2),i.status==='draft'?'Borrador':'Emitida de prueba']})];download('\ufeff'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n'),'claro-facturas.csv','text/csv;charset=utf-8');toast('Exportación descargada');}
function reviewDraft(){clearTimeout(saveTimer);saveDraft();errors=validate(active,client(active),company(active));if(active.originalId&&!active.reason?.trim())errors.push(['reason','Indica el motivo de la rectificación.']);page=errors.length?'editor':'review';render();window.scrollTo(0,0);}
async function issue(){if(active.status!=='draft')return;const issueId=active.id;const work=()=>{let latest;try{latest=JSON.parse(localStorage.getItem(KEY));}catch{}if(!latest){toast('Guarda el borrador antes de emitir.');return;}const item=latest.invoices.find(x=>x.id===issueId);if(!item){toast('No se encuentra el borrador. Recarga la página.');return;}if(item.status!=='draft'){db=latest;active=item;render();return;}const c=latest.clients.find(x=>x.id===item.clientId);if(validate(item,c,latest.company).length){toast('Revisa los datos del borrador antes de emitir.');return;}item.number=nextNumber(latest.invoices,item.date,!!item.originalId);item.status='issued';item.issuedAt=new Date().toISOString();item.clientSnapshot=structuredClone(c);item.companySnapshot=structuredClone(latest.company);db=latest;active=item;if(persist()){render();toast('Documento de prueba emitido · '+item.number);}else{item.status='draft';item.number=null;render();}};if(navigator.locks)await navigator.locks.request('claro-issue',work);else work();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.nav){navigate(b.dataset.nav);return;}if(b.dataset.tab){tab=b.dataset.tab;invoices();return;}if(b.dataset.open){saveDraft();active=db.invoices.find(i=>i.id===b.dataset.open);page=active.status==='draft'?'editor':'review';errors=[];render();window.scrollTo(0,0);return;}if(b.dataset.editClient){clientModal(b.dataset.editClient);return;}if(b.dataset.removeLine!==undefined){active.lines.splice(Number(b.dataset.removeLine),1);saveDraft();editor();return;}if(b.dataset.menu){const i=db.invoices.find(x=>x.id===b.dataset.menu);modal.innerHTML=`<button class="iconbtn close" data-action="close-modal" aria-label="Cerrar">${icon('close')}</button><h2 style="margin-bottom:20px">${esc(i.number||'Borrador')}</h2><button class="menu-item" data-menu-open="${i.id}">${icon(i.status==='draft'?'edit':'invoice')} ${i.status==='draft'?'Continuar borrador':'Ver documento'}</button><button class="menu-item" data-copy="${i.id}">${icon('copy')} Duplicar como borrador</button>`;modal.showModal();return;}if(b.dataset.menuOpen){modal.close();active=db.invoices.find(x=>x.id===b.dataset.menuOpen);page=active.status==='draft'?'editor':'review';errors=[];render();return;}if(b.dataset.copy){modal.close();newInvoice(db.invoices.find(x=>x.id===b.dataset.copy));return;}switch(b.dataset.action){case'new':newInvoice();break;case'help':showHelp();break;case'close-modal':modal.close();break;case'new-client':clientModal();break;case'add-line':active.lines.push({description:'',qty:1,price:'',tax:21});saveDraft();editor();document.querySelector(`[data-line="${active.lines.length-1}"]`).focus();break;case'review':reviewDraft();break;case'save-close':saveDraft();navigate('invoices');toast('Borrador guardado');break;case'back-edit':page='editor';editor();break;case'back-list':navigate('invoices');break;case'issue':issue();break;case'print':window.print();break;case'duplicate':newInvoice(active);break;case'rectify':newInvoice(active,true);toast('Indica los datos corregidos y el motivo. Rectificativa de prueba por sustitución.');break;case'export':csvExport();break;case'backup':download(JSON.stringify(db,null,2),'claro-copia-'+today()+'.json','application/json');break;case'restore':document.querySelector('#backup-file').click();break;case'clear-filters':query='';tab='all';month='all';invoices();break;case'confirm-restore':db=JSON.parse(modal.dataset.backup);active=null;persist();modal.close();settings();toast('Copia restaurada');break;}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='search'){query=el.value;document.querySelector('#rows').innerHTML=invoiceRows();document.querySelector('#result-count').textContent=`${filtered().length} de ${db.invoices.length} facturas`;return;}if(el.id==='client-search'){clientQuery=el.value;document.querySelector('#client-cards').innerHTML=clientCards(db.clients.filter(c=>(c.name+' '+c.nif).toLowerCase().includes(clientQuery.toLowerCase())));return;}if(page!=='editor')return;if(el.dataset.line!==undefined){const n=Number(el.dataset.line);active.lines[n][el.dataset.key]=el.value;document.querySelector(`[data-line-total="${n}"]`).textContent=money(Math.round((numeric(active.lines[n].qty)||0)*(numeric(active.lines[n].price)||0)*100)/100);document.querySelector('#summary-values').innerHTML=sumHTML(active);}else if(['notes','reason','date'].includes(el.id)){active[el.id]=el.value;}else return;const status=document.querySelector('.save-status');if(status)status.textContent='Guardando…';clearTimeout(saveTimer);saveTimer=setTimeout(saveDraft,350);});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='client'){active.clientId=el.value;saveDraft();editor();}if(el.id==='month'){month=el.value;invoices();}if(el.id==='sort'){sort=el.value;invoices();}if(el.id==='backup-file'&&el.files[0]){try{if(el.files[0].size>5000000)throw Error();const raw=await el.files[0].text(),data=JSON.parse(raw);if(data.version!==1||!data.company||!Array.isArray(data.clients)||!Array.isArray(data.invoices)||data.invoices.some(i=>!Array.isArray(i.lines)||!['draft','issued'].includes(i.status)||!/^\d{4}-\d{2}-\d{2}$/.test(i.date)||i.lines.some(l=>typeof l.description!=='string'||!Number.isFinite(numeric(l.qty))||!Number.isFinite(numeric(l.price))))||data.clients.some(c=>typeof c.name!=='string'||!c.id))throw Error();modal.dataset.backup=JSON.stringify(data);modal.innerHTML=`<h2>Restaurar copia</h2><p>Se sustituirán los datos de este navegador por ${data.invoices.length} facturas y ${data.clients.length} clientes de la copia. Descarga antes una copia de los datos actuales si quieres conservarlos.</p><div class="actions"><button class="btn" data-action="close-modal">Cancelar</button><button class="btn primary" data-action="confirm-restore">Restaurar copia</button></div>`;modal.showModal();}catch{toast('La copia no tiene un formato válido o supera 5 MB.');}el.value='';}});
document.addEventListener('submit',e=>{if(e.target.id==='client-form'){e.preventDefault();const data=Object.fromEntries(new FormData(e.target));Object.keys(data).forEach(k=>data[k]=data[k].trim());if(!data.name||!data.nif||!data.address){toast('Completa los datos del cliente.');return;}const id=e.target.dataset.id;if(id){Object.assign(db.clients.find(c=>c.id===id),data);}else{data.id=crypto.randomUUID();data.color=db.clients.length%5;db.clients.push(data);if(page==='editor')active.clientId=data.id;}persist();modal.close();render();toast('Datos del cliente guardados');}if(e.target.id==='settings-form'){e.preventDefault();const data=Object.fromEntries(new FormData(e.target));Object.keys(data).forEach(k=>data[k]=data[k].trim());if(!data.name||!data.nif||!data.address){toast('Completa los datos de la empresa.');return;}db.company=data;persist();settings();toast('Datos de empresa actualizados');}});
window.addEventListener('pagehide',()=>{clearTimeout(saveTimer);saveDraft();});
window.addEventListener('storage',e=>{if(e.key!==KEY||!e.newValue)return;if(page==='editor'){toast('Hay cambios en otra pestaña. Termina aquí antes de seguir en otra.');return;}try{db=JSON.parse(e.newValue);if(active)active=db.invoices.find(i=>i.id===active.id);render();}catch{}});
try{if(!localStorage.getItem(KEY))persist();}catch{storageOK=false;}render();
